import{_ as t,o as a,c as r,ag as n}from"./chunks/framework.DqVSm8kp.js";const p=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/index.md","filePath":"fr/guide/index.md"}'),s={name:"fr/guide/index.md"};function o(i,e,l,d,u,c){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p><strong>LLMxRay</strong> est un tableau de bord gratuit et local-first qui se connecte a <a href="https://ollama.com" target="_blank" rel="noreferrer">Ollama</a> sur votre machine. Il vous permet de discuter avec n&#39;importe quel modele telecharge puis d&#39;inspecter tout ce qui s&#39;est passe en coulisses : la vitesse d&#39;arrivee de chaque token, ce que le modele a pu &quot;penser&quot;, comment differents parametres modifient la sortie, et bien plus encore.</p><p><strong>Pas de cloud. Pas de cles API. Aucun cout.</strong> Tout s&#39;execute sur votre materiel.</p><h2 id="a-qui-s-adresse-llmxray" tabindex="-1">A qui s&#39;adresse LLMxRay ? <a class="header-anchor" href="#a-qui-s-adresse-llmxray" aria-label="Permalink to &quot;A qui s&#39;adresse LLMxRay ?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Vous etes...</th><th>LLMxRay vous aide a...</th></tr></thead><tbody><tr><td><strong>Debutant curieux</strong></td><td>Voir les reponses de l&#39;IA se former en temps reel et comprendre ce que signifient vraiment &quot;temperature&quot; ou &quot;tokens&quot;</td></tr><tr><td><strong>Etudiant / enseignant</strong></td><td>Explorer visuellement le comportement des modeles -- ideal pour les cours et demonstrations en IA/ML</td></tr><tr><td><strong>Developpeur</strong></td><td>Deboguer les prompts, comparer les modeles, profiler la latence, inspecter les appels d&#39;outils</td></tr><tr><td><strong>Chercheur</strong></td><td>Mener des experiences controlees : meme prompt, parametres differents, resultats cote a cote</td></tr></tbody></table><h2 id="navigation-dans-l-application" tabindex="-1">Navigation dans l&#39;application <a class="header-anchor" href="#navigation-dans-l-application" aria-label="Permalink to &quot;Navigation dans l&#39;application&quot;">​</a></h2><p>LLMxRay dispose d&#39;une barre laterale avec 10 elements de navigation, chacun representant une fonctionnalite majeure. Ce guide comporte un chapitre par element, dans l&#39;ordre exact d&#39;apparition dans la barre laterale :</p><ol><li><strong><a href="./chat-diagnostics.html">Diagnostics de Chat</a></strong> -- L&#39;interface de chat principale avec streaming et analyse de session</li><li><strong><a href="./compare.html">Comparer</a></strong> -- Comparaison cote a cote de modeles et de parametres</li><li><strong><a href="./embeddings.html">Plongements</a></strong> -- Visualisation d&#39;embeddings textuels et similarite</li><li><strong><a href="./knowledge-base.html">Base de Connaissances</a></strong> -- Telechargement de documents, decoupage et recherche RAG</li><li><strong><a href="./tool-workshop.html">Atelier d&#39;Outils</a></strong> -- Constructeur visuel d&#39;outils avec synchronisation du code</li><li><strong><a href="./ai-training.html">Entrainement IA</a></strong> -- Curation et export de donnees d&#39;entrainement</li><li><strong><a href="./models.html">Modeles</a></strong> -- Navigateur de modeles et detection des capacites</li><li><strong><a href="./benchmark.html">Benchmark</a></strong> -- Evaluation standardisee des modeles avec logprobs</li><li><strong><a href="./system.html">Mon Systeme</a></strong> -- Detection du materiel et statut d&#39;Ollama</li><li><strong><a href="./settings.html">Parametres</a></strong> -- Connexion, parametres et preferences</li></ol><h2 id="autres-elements" tabindex="-1">Autres elements <a class="header-anchor" href="#autres-elements" aria-label="Permalink to &quot;Autres elements&quot;">​</a></h2><ul><li><strong>Barre d&#39;en-tete</strong> -- Affiche le titre de la page courante, un bouton de theme (sombre/clair) et le statut de connexion a Ollama (vert = connecte, rouge = deconnecte).</li><li><strong>Bouton de retour d&#39;experience</strong> -- En bas de la barre laterale. Ouvre une fenetre superposee pour soumettre directement vos commentaires.</li></ul><h2 id="etapes-suivantes" tabindex="-1">Etapes suivantes <a class="header-anchor" href="#etapes-suivantes" aria-label="Permalink to &quot;Etapes suivantes&quot;">​</a></h2><p>Si vous n&#39;avez pas encore installe LLMxRay, rendez-vous sur la page <a href="./installation.html">Installation</a>. Sinon, choisissez n&#39;importe quel chapitre dans la barre laterale pour commencer a explorer.</p>',12)])])}const h=t(s,[["render",o]]);export{p as __pageData,h as default};
